mapper.sql:
 FROM "signposts" "s"
 JOIN "bus_stops" "b"
   ON "b"."del_flag"               = 0
  AND "b"."available_flag"         = 1
  AND "b"."business_corp_id"       = #{businessCorpId}
  AND "b"."bus_stop_id"            = "s"."bus_stop_id"
 JOIN "agencies" "a"
   ON "a"."del_flag"               = 0
  AND "a"."available_flag"         = 1
  AND "a"."business_corp_id"       = "b"."business_corp_id"
WHERE "s"."del_flag"               = 0

     AND "s"."bus_stop_id"            = #{busStopId}


     AND "s"."signpost_branch_number" = #{signpostBranchNumber}


     AND "s"."signpost_name"       LIKE #{likeSearchSignpostName}


     AND "s"."available_flag"         = #{availableFlag}

mapper.insert:
INSERT INTO "signposts" ( "bus_stop_id" , "signpost_branch_number" , "signpost_code" , "signpost_name" , "signpost_kana_name" , "signpost_en_name" , "address" , "place_name" , "signpost_desc" , "signpost_url" , "bus_stop_type" , "platform_code" , "available_flag" , "signpost_sub_name" , "latitude_longitude" , "wheelchair_accessible_type" , "arrival_point" , "arrival_point_radius"
) VALUES ( CAST(#{busStopId} AS INTEGER) , CAST(COALESCE(#{signpostBranchNumber}, '0') AS INTEGER) , COALESCE(#{signpostCode}, '') , COALESCE(#{signpostName}, '') , COALESCE(#{signpostKanaName}, '') , COALESCE(#{signpostEnName}, '') , COALESCE(#{address}, '') , COALESCE(#{placeName}, '') , COALESCE(#{signpostDesc}, '') , COALESCE(#{signpostUrl}, '') , 0 , COALESCE(#{platformCode}, '') , 1 , COALESCE(#{signpostSubName}, '') , COALESCE(#{latitudeLongitude}, '') , CAST(COALESCE(#{wheelchairAccessibleType}, '0') AS SMALLINT) , COALESCE(#{arrivalPoint}, '') , CAST(#{arrivalPointRadius} AS INTEGER)
)
